item.content:encoded:
/* ======== WPForms - TEXT ALB FORȚAT ======== */

/* Etichete - SUPER IMPORTANT */
.wpforms-container .wpforms-field-label,
.wpforms-container .wpforms-field-sublabel,
.wpforms-container .wpforms-field-description,
.wpforms-container label,
.wpforms-container legend,
label.wpforms-field-label,
.wpforms-field-label,
.wpforms-container .wpforms-field label {
    color: #ffffff !important;
    opacity: 1 !important;
}

/* Input-uri cu fundal semi-transparent */
.wpforms-container input[type="text"],
.wpforms-container input[type="email"],
.wpforms-container input[type="tel"],
.wpforms-container input[type="url"],
.wpforms-container input[type="number"],
.wpforms-container select,
.wpforms-container textarea {
    background: rgba(255, 255, 255, 0.1) !important;
    border: 1px solid rgba(255, 255, 255, 0.3) !important;
    color: #ffffff !important;
    border-radius: 6px !important;
    padding: 12px 15px !important;
}

/* Placeholder alb */
.wpforms-container input::placeholder,
.wpforms-container textarea::placeholder {
    color: rgba(255, 255, 255, 0.6) !important;
    opacity: 1 !important;
}

/* Focus */
.wpforms-container input:focus,
.wpforms-container select:focus,
.wpforms-container textarea:focus {
    border-color: #ff5722 !important;
    box-shadow: 0 0 8px rgba(255, 87, 34, 0.5) !important;
    background: rgba(255, 255, 255, 0.15) !important;
    outline: none !important;
}

/* Butoane portocalii */
.wpforms-container .wpforms-submit,
.wpforms-container button[type="submit"],
.wpforms-container input[type="submit"],
.wpforms-container .wpforms-page-next,
.wpforms-container .wpforms-page-prev {
    background: #ff5722 !important;
    color: #ffffff !important;
    border: none !important;
    padding: 14px 30px !important;
    font-size: 16px !important;
    font-weight: 600 !important;
    border-radius: 6px !important;
    cursor: pointer !important;
}

/* Hover butoane */
.wpforms-container .wpforms-submit:hover,
.wpforms-container button[type="submit"]:hover {
    background: #e64a19 !important;
}

/* Radio si checkbox portocalii */
.wpforms-container input[type="radio"],
.wpforms-container input[type="checkbox"] {
    accent-color: #ff5722 !important;
}

/* Select dropdown */
.wpforms-container select {
    background: rgba(255, 255, 255, 0.1) !important;
    color: #ffffff !important;
}

/* Progress bar */
.wpforms-container .wpforms-page-indicator {
    color: #ffffff !important;
}

/* Background body - cover */
body,
body.dark-mood {
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
}

/* Elimină overflow */
html, body {
    overflow-x: hidden !important;
    max-width: 100vw !important;
}

